def solve(a, b):
    """Return Levenshtein distance between strings a and b.
    Uses classic DP for small inputs and Myers' bit‑parallel algorithm for larger inputs.
    """
    # Helper: classic DP O(len(a)*len(b)) time, O(min) space
    def dp(x, y):
        if len(x) < len(y):
            x, y = y, x
        prev = list(range(len(y) + 1))
        for i, cx in enumerate(x, 1):
            cur = [i]
            for j, cy in enumerate(y, 1):
                cur.append(min(cur[-1] + 1,          # insertion
                               prev[j] + 1,          # deletion
                               prev[j - 1] + (cx != cy)))  # substitution
            prev = cur
        return prev[-1]

    # Helper: Myers' bit‑parallel algorithm (unit costs)
    def bit_parallel(x, y):
        # Ensure x is the shorter pattern for bit‑vector size
        if len(x) > len(y):
            x, y = y, x
        n = len(x)
        if n == 0:
            return len(y)
        # Build character bit masks for pattern x
        Peq = {}
        for i, ch in enumerate(x):
            Peq[ch] = Peq.get(ch, 0) | (1 << i)
        # Initialise VP, VN and current distance
        VP = (1 << n) - 1  # all bits 1
        VN = 0
        curr = n          # distance when y is empty
        mask = (1 << n) - 1
        highbit = 1 << (n - 1)
        for ch in y:
            Eq = Peq.get(ch, 0)
            X = Eq | VN
            D0 = (((X & VP) + VP) ^ VP) | X
            HN = VP & D0
            HP = VN | ~(VP | D0)
            VN = (HP << 1) | 1
            VP = (HN << 1) | ~D0
            VN &= mask
            VP &= mask
            # Update current edit distance according to Myers' rules
            if D0 & highbit:
                curr += 1
            elif HP & highbit:
                curr -= 1
        return curr

    # Choose algorithm based on input size. The threshold balances time/memory.
    if len(a) * len(b) <= 500_000:  # about 0.5 million cell updates is cheap
        return dp(a, b)
    else:
        return bit_parallel(a, b)

