def solve(grid):
    """Count the number of islands in a possibly ragged binary grid.
    An island is a group of orthogonally adjacent cells with value 1.
    """
    if not grid:
        return 0
    m = len(grid)
    visited = set()
    def neighbors(r, c):
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < m and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if (i,j) in visited:
                continue
            visited.add((i,j))
            for ni, nj in neighbors(i,j):
                if (ni,nj) not in visited and grid[ni][nj] == 1:
                    stack.append((ni,nj))
    count = 0
    for i in range(m):
        row_len = len(grid[i])
        for j in range(row_len):
            if grid[i][j] == 1 and (i,j) not in visited:
                dfs(i,j)
                count += 1
    return count

